var doubleIt = function(head) {
    if (head && head.val >= 5) {
        head = new ListNode(0, head);
    }
    let curr = head;
    while (curr) {
        const carry = (curr.next && curr.next.val >= 5) ? 1 : 0;
        curr.val = (curr.val * 2 + carry) % 10;
        curr = curr.next;
    }
    return head;
};
